# sync-template.ps1
# Mirrors template/.agents/skills/ into template/.claude/skills/.
#
# template/.agents/skills/ is the source of truth: Codex, Copilot, VS Code,
# Cursor, Gemini CLI, OpenCode and most other agents read it. Claude Code reads
# only .claude/skills/, so it gets a generated byte-for-byte copy.
#
#   .\scripts\sync-template.ps1          Rewrite the copy
#   .\scripts\sync-template.ps1 -Check   Report drift and exit 1 if any (CI)
#
# Runs on Windows PowerShell 5.1 and PowerShell 7.

param(
    [switch]$Check
)

$ErrorActionPreference = 'Stop'
$root   = Split-Path -Parent $PSScriptRoot
$source = Join-Path $root 'template/.agents/skills'
$target = Join-Path $root 'template/.claude/skills'

function Get-Tree([string]$Dir) {
    $map = @{}
    if (-not (Test-Path -LiteralPath $Dir)) { return $map }
    $base = (Resolve-Path -LiteralPath $Dir).Path.TrimEnd('\', '/')
    Get-ChildItem -LiteralPath $Dir -Recurse -File -Force | ForEach-Object {
        $rel = $_.FullName.Substring($base.Length + 1) -replace '\\', '/'
        $map[$rel] = (Get-FileHash -LiteralPath $_.FullName -Algorithm SHA256).Hash
    }
    return $map
}

$src = Get-Tree $source
$dst = Get-Tree $target

$drift = @()
foreach ($rel in $src.Keys) {
    if (-not $dst.ContainsKey($rel))      { $drift += "missing  $rel" }
    elseif ($dst[$rel] -ne $src[$rel])    { $drift += "differs  $rel" }
}
foreach ($rel in $dst.Keys) {
    if (-not $src.ContainsKey($rel))      { $drift += "extra    $rel" }
}

if ($Check) {
    if ($drift.Count -eq 0) {
        Write-Host "OK   template/.claude/skills matches template/.agents/skills ($($src.Count) files)"
        exit 0
    }
    Write-Host "DRIFT template/.claude/skills is out of date. Run scripts/sync-template.ps1:"
    $drift | Sort-Object | ForEach-Object { Write-Host "  $_" }
    exit 1
}

if (Test-Path -LiteralPath $target) {
    Remove-Item -LiteralPath $target -Recurse -Force
}
New-Item -ItemType Directory -Force -Path $target | Out-Null
Get-ChildItem -LiteralPath $source -Force | ForEach-Object {
    Copy-Item -LiteralPath $_.FullName -Destination $target -Recurse -Force
}

$after = Get-Tree $target
Write-Host "OK   mirrored $($after.Count) files into template/.claude/skills"
